    public string Language => _language;
    public string this[string key] => ( _language == "en" ? English : Arabic).TryGetValue(key, out var value) ? value : key;
    public string Get(string key) => this[key];
    public string EvidenceLabel(string label) => label switch
    {
        "Game executable" => _language == "en" ? "Game executable" : "الملف التنفيذي للعبة",
        "Build metadata" => _language == "en" ? "Build metadata" : "بيانات البناء",
        "Game data" => _language == "en" ? "Game data" : "بيانات اللعبة",
        "Local launcher" => _language == "en" ? "Local launcher" : "مشغّل اللعبة المحلي",
        "Executable product" => _language == "en" ? "Executable product" : "هوية الملف التنفيذي",
        "Executable file version" => _language == "en" ? "Executable file version" : "إصدار الملف التنفيذي",
        "Build product" => _language == "en" ? "Build product" : "منتج البناء",
        "Build version" => _language == "en" ? "Build version" : "إصدار البناء",
        "Build branch" => _language == "en" ? "Build branch" : "فرع البناء",
        "Executable SHA-256" => _language == "en" ? "Executable SHA-256" : "بصمة الملف التنفيذي SHA-256",
        _ => label
    };
    public void SetLanguage(string language)
    {
        _language = language == "en" ? "en" : "ar";
        CultureInfo.CurrentUICulture = CultureInfo.GetCultureInfo(_language == "ar" ? "ar-SA" : "en-US");
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(Language)));
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs("Item[]"));
    }

